import { getIsoBaseMediaChildren } from '../get-children';
export const parseTrak = async ({ size, offsetAtStart, state: options, }) => {
    const children = await getIsoBaseMediaChildren({
        state: options,
        size: size - 8,
    });
    return {
        offset: offsetAtStart,
        boxSize: size,
        type: 'trak-box',
        children,
    };
};
